async function loadReport(file){
  $('#reportName').textContent=file.name;
  $('#reportBadge').textContent=file.name;
  const body=$('#reportBody');
  body.innerHTML='';
  const name=file.name.toLowerCase();
  const isDocx=name.endsWith('.docx');
  const isDoc=name.endsWith('.doc');
  if(file.type==='application/pdf'||name.endsWith('.pdf')){
    const f=document.createElement('iframe');f.className='report-frame';f.src=URL.createObjectURL(file);body.append(f);
  }else if(file.type.startsWith('image/')){
    const i=document.createElement('img');i.className='report-image';i.src=URL.createObjectURL(file);body.append(i);
  }else if(isDocx){
    if(!window.mammoth){showReportMessage(body,'Word preview is unavailable because the document viewer could not be loaded.');return;}
    showReportMessage(body,'Loading Word document…');
    try{
      const result=await window.mammoth.convertToHtml({arrayBuffer:await file.arrayBuffer()});
      body.innerHTML='';
      const article=document.createElement('article');article.className='report-docx';article.innerHTML=result.value;body.append(article);
      if(result.messages?.length) console.warn('Word document conversion messages:',result.messages);
    }catch(error){showReportMessage(body,`Could not display this Word document: ${error.message}`)}
  }else if(isDoc){
    showReportMessage(body,'Legacy .doc files cannot be previewed in the browser. Please save the report as .docx or PDF and upload it again.');
  }else{
    const reader=new FileReader();reader.onload=()=>{const p=document.createElement('div');p.className='report-text';p.textContent=reader.result;body.innerHTML='';body.append(p)};reader.readAsText(file);
  }
}
