function renderOverlayLegend(){const host=$('#branchOverlayLegend');if(!branches.length){host.innerHTML='<div class="compare-empty">No branches uploaded yet.</div>';return}host.innerHTML=branches.map((f,i)=>`<div class="overlay-legend-item"><span class="overlay-legend-swatch" style="background:${overlayColorCss(overlayColor(i))}"></span><span class="overlay-legend-number">${String(i+1).padStart(2,'0')}</span><span class="overlay-legend-name" title="${f.name}">${f.name}</span></div>`).join('')}
function overlayImageLayer(file,index,ctx,w,h){return new Promise(resolve=>{const img=new Image();img.onload=()=>{const temp=document.createElement('canvas');temp.width=w;temp.height=h;const t=temp.getContext('2d');t.drawImage(img,0,0,w,h);const src=t.getImageData(0,0,w,h),out=document.createElement('canvas');out.width=w;out.height=h;const o=out.getContext('2d'),pixels=o.createImageData(w,h),c=overlayColor(index);for(let p=0;p<src.data.length;p+=4){const a=src.data[p+3]||Math.max(src.data[p],src.data[p+1],src.data[p+2]);if(a>12){pixels.data[p]=c[0]*255;pixels.data[p+1]=c[1]*255;pixels.data[p+2]=c[2]*255;pixels.data[p+3]=Math.min(220,a)}}o.putImageData(pixels,0,0);ctx.drawImage(out,0,0);resolve()};img.onerror=resolve;img.src=URL.createObjectURL(file)})}
function renderOverlayGpu(volumes,host){const canvas=document.createElement('canvas');canvas.className='branch-overlay-image-canvas';host.innerHTML='';host.append(canvas);const gl=canvas.getContext('webgl2',{antialias:false,alpha:false})||canvas.getContext('webgl',{antialias:false,alpha:false});if(!gl)throw Error('WebGL is unavailable');const total=volumes.reduce((n,v)=>n+v.dims[0]*v.dims[1]*v.dims[2],0),step=Math.max(1,Math.ceil(Math.cbrt(total/180000))),positions=[],colors=[];volumes.forEach((volume,vi)=>{const [w,h,d]=volume.dims,c=vi===0&&volumes.length>1?[.20,.43,.39]:overlayColor(vi-(wholeVolume3d?1:0)),alpha=vi===0&&volumes.length>1?.18:.92;for(let z=0;z<d;z+=step)for(let y=0;y<h;y+=step)for(let x=0;x<w;x+=step){const idx=x+y*w+z*w*h;if(volume.values[idx]>0){positions.push(x/Math.max(1,w-1)*2-1,y/Math.max(1,h-1)*2-1,z/Math.max(1,d-1)*2-1);colors.push(c[0],c[1],c[2],alpha)}}});if(!positions.length)throw Error('The masks contain no non-zero voxels');const shader=(type,source)=>{const s=gl.createShader(type);gl.shaderSource(s,source);gl.compileShader(s);if(!gl.getShaderParameter(s,gl.COMPILE_STATUS))throw Error(gl.getShaderInfoLog(s)||'WebGL shader error');return s};const program=gl.createProgram();gl.attachShader(program,shader(gl.VERTEX_SHADER,'attribute vec3 position;attribute vec4 color;uniform float rx;uniform float ry;varying vec4 vColor;void main(){float cy=cos(ry),sy=sin(ry),cx=cos(rx),sx=sin(rx);vec3 q=vec3(cy*position.x+sy*position.z,position.y,-sy*position.x+cy*position.z);q=vec3(q.x,cx*q.y-sx*q.z,sx*q.y+cx*q.z);gl_Position=vec4(q.xy*.86,q.z,1.0);gl_PointSize=2.8;vColor=color;}'));gl.attachShader(program,shader(gl.FRAGMENT_SHADER,'precision mediump float;varying vec4 vColor;void main(){vec2 p=gl_PointCoord-.5;if(dot(p,p)>.25)discard;gl_FragColor=vColor;}'));gl.linkProgram(program);if(!gl.getProgramParameter(program,gl.LINK_STATUS))throw Error('WebGL program could not be linked');const pb=gl.createBuffer(),cb=gl.createBuffer();gl.bindBuffer(gl.ARRAY_BUFFER,pb);gl.bufferData(gl.ARRAY_BUFFER,new Float32Array(positions),gl.STATIC_DRAW);gl.bindBuffer(gl.ARRAY_BUFFER,cb);gl.bufferData(gl.ARRAY_BUFFER,new Float32Array(colors),gl.STATIC_DRAW);const pl=gl.getAttribLocation(program,'position'),cl=gl.getAttribLocation(program,'color'),rx=gl.getUniformLocation(program,'rx'),ry=gl.getUniformLocation(program,'ry');let ax=-.35,ay=.65,drag=false,lastX=0,lastY=0,raf=0;const draw=()=>{raf=0;const dpr=Math.min(2,window.devicePixelRatio||1),w=Math.max(1,host.clientWidth),h=Math.max(1,host.clientHeight);canvas.width=w*dpr;canvas.height=h*dpr;canvas.style.width=w+'px';canvas.style.height=h+'px';gl.viewport(0,0,canvas.width,canvas.height);gl.clearColor(.93,.96,.95,1);gl.clear(gl.COLOR_BUFFER_BIT|gl.DEPTH_BUFFER_BIT);gl.enable(gl.BLEND);gl.blendFunc(gl.SRC_ALPHA,gl.ONE_MINUS_SRC_ALPHA);gl.useProgram(program);gl.bindBuffer(gl.ARRAY_BUFFER,pb);gl.enableVertexAttribArray(pl);gl.vertexAttribPointer(pl,3,gl.FLOAT,false,0,0);gl.bindBuffer(gl.ARRAY_BUFFER,cb);gl.enableVertexAttribArray(cl);gl.vertexAttribPointer(cl,4,gl.FLOAT,false,0,0);gl.uniform1f(rx,ax);gl.uniform1f(ry,ay);gl.drawArrays(gl.POINTS,0,positions.length/3)};const schedule=()=>{if(!raf)raf=requestAnimationFrame(draw)};canvas.onpointerdown=e=>{drag=true;lastX=e.clientX;lastY=e.clientY;canvas.setPointerCapture(e.pointerId)};canvas.onpointerup=()=>drag=false;canvas.onpointercancel=()=>drag=false;canvas.onpointermove=e=>{if(!drag)return;ay+=(e.clientX-lastX)*.008;ax+=(e.clientY-lastY)*.008;lastX=e.clientX;lastY=e.clientY;schedule()};new ResizeObserver(schedule).observe(host);draw();host.dataset.renderMode='GPU WebGL';return true}
function reduceSurfaceVolume(volume,maxAxis=144){const maxDim=Math.max(...volume.dims),factor=Math.max(1,Math.ceil(maxDim/maxAxis));if(factor===1)return volume;const [w,h,d]=volume.dims,nw=Math.ceil(w/factor),nh=Math.ceil(h/factor),nd=Math.ceil(d/factor),values=new Uint8Array(nw*nh*nd);for(let z=0;z<d;z++){const oz=Math.floor(z/factor);for(let y=0;y<h;y++){const oy=Math.floor(y/factor),row=z*w*h+y*w;for(let x=0;x<w;x++)if(volume.values[row+x]>0){const ox=Math.floor(x/factor);values[ox+oy*nw+oz*nw*nh]=1}}}return {dims:[nw,nh,nd],values,spacing:volume.spacing.map(v=>v*factor)}}
function renderOverlaySurface(volumes,host){if(!window.vtk?.Filters?.General?.vtkImageMarchingCubes)throw Error('Surface renderer unavailable');disposeWrap(host);host.innerHTML='';const grw=vtk.Rendering.Misc.vtkGenericRenderWindow.newInstance({background:[.93,.96,.95]});grw.setContainer(host);grw.resize();const renderer=grw.getRenderer(),rw=grw.getRenderWindow();volumes.forEach((source,vi)=>{const volume=reduceSurfaceVolume(source,vi===0&&volumes.length>1?128:144),imageData=vtk.Common.DataModel.vtkImageData.newInstance();imageData.setDimensions(...volume.dims);imageData.setSpacing(...volume.spacing);imageData.getPointData().setScalars(vtk.Common.Core.vtkDataArray.newInstance({name:'Mask',values:volume.values,numberOfComponents:1}));const contour=vtk.Filters.General.vtkImageMarchingCubes.newInstance({contourValue:.5,computeNormals:false,mergePoints:true});contour.setInputData(imageData);contour.update();const mapper=vtk.Rendering.Core.vtkMapper.newInstance();mapper.setInputConnection(contour.getOutputPort());const actor=vtk.Rendering.Core.vtkActor.newInstance();actor.setMapper(mapper);const prop=actor.getProperty(),c=vi===0&&volumes.length>1?[.20,.43,.39]:overlayColor(vi-(wholeVolume3d?1:0));prop.setColor(...c);prop.setOpacity(vi===0&&volumes.length>1?.18:.92);prop.setAmbient(.35);prop.setDiffuse(.65);prop.setSpecular(0);renderer.addActor(actor)});renderer.resetCamera();rw.render();volumeViews.set(host,grw);host.dataset.renderMode='GPU WebGL surface'}
async function refreshBranchOverlay(){renderOverlayLegend();const host=$('#branchOverlayCanvas');host.innerHTML='<div class="branch-overlay-loading">Loading branch overlays…</div>';overlayVolumes=[];overlayImages=[];if(!branches.length){host.innerHTML='<div class="compare-empty">Upload branch masks to view the overlay.</div>';return}try{for(const file of branches){if(/\.nii(\.gz)?$/i.test(file.name))overlayVolumes.push(await readNiftiVolume(file));else overlayImages.push(file)}if(overlayVolumes.length&&overlayImages.length===0){const volumes=wholeVolume3d?[wholeVolume3d,...overlayVolumes]:overlayVolumes;try{renderOverlaySurface(volumes,host)}catch(e){try{const items=[];if(wholeVolume3d)items.push({volume:wholeVolume3d,color:[.16,.38,.34],opacity:.22});overlayVolumes.forEach((volume,i)=>items.push({volume,color:overlayColor(i),opacity:.95}));renderVtkVolumes(items,host,{style:{display:'none'}})}catch(e2){renderOverlayGpu(volumes,host)}}}else{const first=new Image();first.onload=async()=>{host.innerHTML='';const canvas=document.createElement('canvas');canvas.className='branch-overlay-image-canvas';const wrap=host.getBoundingClientRect();const maxW=Math.max(1,Math.floor(wrap.width)),maxH=Math.max(1,Math.floor(wrap.height));const scale=Math.min(maxW/first.width,maxH/first.height);canvas.width=Math.max(1,Math.floor(first.width*scale));canvas.height=Math.max(1,Math.floor(first.height*scale));host.append(canvas);const ctx=canvas.getContext('2d');ctx.fillStyle='#dce8e4';ctx.fillRect(0,0,canvas.width,canvas.height);if(wholeFile&&wholeFile.type.startsWith('image/')){const bg=new Image();bg.onload=()=>{ctx.globalAlpha=.22;ctx.drawImage(bg,0,0,canvas.width,canvas.height);ctx.globalAlpha=1;overlayImages.reduce((p,f,i)=>p.then(()=>overlayImageLayer(f,i,ctx,canvas.width,canvas.height)),Promise.resolve())};bg.src=URL.createObjectURL(wholeFile)}else overlayImages.reduce((p,f,i)=>p.then(()=>overlayImageLayer(f,i,ctx,canvas.width,canvas.height)),Promise.resolve())};first.src=URL.createObjectURL(overlayImages[0])}}catch(e){host.innerHTML=`<div class="compare-empty">Could not build overlay: ${e.message}</div>`}}
$('#overlayBtn').onclick=()=>{$('#branchOverlay').hidden=false;renderOverlayLegend();requestAnimationFrame(()=>refreshBranchOverlay());document.documentElement.requestFullscreen?.().catch(()=>{})};$('#closeBranchOverlay').onclick=()=>{if(document.fullscreenElement)document.exitFullscreen();$('#branchOverlay').hidden=true};
$('#resetBtn').addEventListener('click',()=>{overlayVolumes=[];overlayImages=[];if($('#branchOverlay'))$('#branchOverlay').hidden=true});
